select energy_manager.load_cards($cards$[
{"id":"p2-b04-035","paper":2,"topic":"Waste Heat Recovery in Furnaces","kind":"problem","front":"Using the same oil fired reheating furnace (440 litres/hr, 14 kg air per kg oil, 200% excess air), the combustion air is preheated from 35 °C to 200 °C (Cp of air 0.24 kcal/kg °C). Find the heat recovered by the combustion air as a percentage of energy input.","back":"About 16.3% of energy input (about 6,73,263 kcal/hr).","explain":"Preheated combustion air returns heat to the furnace that would otherwise leave in the flue gas. This is why air preheating has a larger effect at higher furnace temperature.","steps":[{"prompt":"Find the actual air mass per kg oil.","answer":"14 × (1 + 200 ÷ 100) = 42 kg/kg oil","explain":"Excess air is 200%, so actual air is three times theoretical."},{"prompt":"Find the heat gained per kg oil: air mass × Cp × (t_preheat − t_ambient).","answer":"42 × 0.24 × (200 − 35) = 1663.2 kcal/kg oil","explain":"Only the rise from ambient to the preheat temperature is useful."},{"prompt":"Find the hourly heat gain.","answer":"1663.2 × 404.8 = 6,73,263 kcal/hr","explain":"Multiply by the oil flow in kg/hr."},{"prompt":"Express as a percentage of the energy input.","answer":"673,263 ÷ 4,128,960 × 100 = 16.3%","explain":"Energy input is 41,28,960 kcal/hr."}],"flash":false,"source":"BEE Book 2 Ch 04 p166","order":2248},
{"id":"p2-b04-036","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"A billet heating furnace has an output of 15 t/hr and efficiency 32%. Billets go from 50 °C to 1150 °C (Cp 0.12 kcal/kg °C). Fuel oil has density 0.95 kg/litre and GCV 10,000 kcal/kg. Find the specific fuel consumption in litres/tonne and the total fuel consumption in litres/hr.","back":"About 43.4 litres per tonne and about 651 litres per hour.","explain":"The efficiency converts useful heat per tonne into fuel heat input. Dividing by GCV gives mass, and dividing by density gives volume. Use the gross calorific value here since the data gives GCV.","steps":[{"prompt":"Find the useful heat per tonne: 1000 × 0.12 × (1150 − 50).","answer":"132,000 kcal per tonne","explain":"Useful heat is the stock heat for one tonne of billet."},{"prompt":"Find the fuel heat input per tonne: useful heat ÷ efficiency.","answer":"132,000 ÷ 0.32 = 412,500 kcal per tonne","explain":"Efficiency is useful output divided by fuel input, so input equals output over efficiency."},{"prompt":"Convert heat input to fuel mass, then volume.","answer":"412,500 ÷ 10,000 = 41.25 kg; 41.25 ÷ 0.95 = 43.4 litres per tonne","explain":"Mass is heat over GCV; litres is mass over density."},{"prompt":"Find the hourly fuel consumption at 15 t/hr.","answer":"43.4 × 15 ≈ 651 litres/hr","explain":"Specific consumption multiplied by hourly output gives total hourly fuel."}],"flash":false,"source":"BEE Book 2 Ch 04 p168","order":2249},
{"id":"p2-b04-037","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"A furnace outputs 5000 kg/hr of billets at 25% thermal efficiency. Billets go from 40 °C to 1200 °C (Cp 0.12 kcal/kg °C). If the oil GCV is 9,200 kcal/litre, find the hourly oil consumption in litres.","back":"About 302.6 litres per hour.","explain":"Here the GCV is given per litre, so no density conversion is needed. The efficiency of 25% means four times the useful heat must be supplied as fuel.","steps":[{"prompt":"Find the useful heat per hour: 5000 × 0.12 × (1200 − 40).","answer":"696,000 kcal/hr","explain":"Useful heat is the heat to bring the billets to temperature."},{"prompt":"Find the fuel heat input: useful heat ÷ efficiency.","answer":"696,000 ÷ 0.25 = 2,784,000 kcal/hr","explain":"Fuel input must cover the useful heat plus all losses."},{"prompt":"Convert heat to litres of oil using GCV per litre.","answer":"2,784,000 ÷ 9,200 ≈ 302.6 litres/hr","explain":"GCV per litre gives litres directly from heat input."}],"flash":false,"source":"BEE Book 2 Ch 04 p168","order":2250},
{"id":"p2-b04-038","paper":2,"topic":"Furnace Efficiency","kind":"problem","front":"A reheating furnace outputs 10 t/hr of billets heated from 500 °C to 1200 °C (Cp 0.12 kcal/kg °C). It burns 700 litres/hr of fuel oil (SG 0.95) with net calorific value 9,650 kcal/kg. Find the thermal efficiency on an NCV basis.","back":"About 13.1%.","explain":"On the NCV basis, the water vapour latent heat is not counted as recovered, so the efficiency is higher than on GCV. The efficiency here is low because the furnace is operating with large losses, which matches the chapter's warning on furnace efficiency.","steps":[{"prompt":"Find the useful heat per hour: 10,000 × 0.12 × (1200 − 500).","answer":"840,000 kcal/hr","explain":"Output is 10 t/hr, so 10,000 kg/hr."},{"prompt":"Find the fuel mass per hour: 700 litres × 0.95.","answer":"665 kg/hr","explain":"Convert litres to kg with specific gravity."},{"prompt":"Find the heat input on an NCV basis: 665 × 9,650.","answer":"6,417,250 kcal/hr","explain":"Use the net calorific value as the chapter specifies for this question."},{"prompt":"Find the efficiency: useful heat ÷ heat input × 100.","answer":"840,000 ÷ 6,417,250 × 100 ≈ 13.1%","explain":"This is the thermal efficiency on the NCV basis."}],"flash":false,"source":"BEE Book 2 Ch 04 p168","order":2251},
{"id":"p2-b05-001","paper":2,"topic":"Purpose of insulation","kind":"fact","front":"List five benefits of thermal insulation.","back":"Reduces overall energy consumption; gives better process control by holding process temperature; prevents corrosion by keeping exposed surfaces above dew point; provides fire protection to equipment; absorbs vibration.","explain":"Energy saving is the main purpose, but insulation also tightens process temperature control and protects personnel. Keeping a surface above dew point stops condensation, which is what causes the corrosion.","flash":false,"source":"BEE Book 2 Ch 05 p173","order":2252},
{"id":"p2-b05-002","paper":2,"topic":"Purpose of insulation","kind":"fact","front":"Why are common insulating materials porous?","back":"They contain many dormant air cells, and still air has very low thermal conductivity, so the trapped air does most of the insulating.","explain":"Heat moves through still air very slowly, so a material full of small trapped air cells conducts little heat. This is the basis of most insulation materials.","flash":false,"source":"BEE Book 2 Ch 05 p173","order":2253},
{"id":"p2-b05-003","paper":2,"topic":"Insulation types","kind":"fact","front":"Up to what temperature does low-temperature insulation cover, and name two materials used in it?","back":"Up to 90 °C; for example cork, wood, 85% magnesia, mineral fibres, polyurethane or expanded polystyrene.","explain":"This group covers refrigerators, cold and hot water systems and storage tanks. The three groups are split by temperature: up to 90 °C, 90 to 325 °C, and above 325 °C.","flash":true,"source":"BEE Book 2 Ch 05 p173","order":2254},
{"id":"p2-b05-004","paper":2,"topic":"Insulation types","kind":"fact","front":"Which insulation group covers temperatures above 325 °C, and what are its typical uses?","back":"High-temperature insulation, used for superheated steam systems, oven dryers and furnaces. Materials include asbestos, calcium silicate, mineral fibre, mica, vermiculite, fireclay or silica, and ceramic fibre.","explain":"Medium-range insulation (90 to 325 °C) covers low-temperature heating equipment, steam lines and flue ducts. The high range needs materials that survive very hot surfaces.","flash":false,"source":"BEE Book 2 Ch 05 p173","order":2255},
{"id":"p2-b05-005","paper":2,"topic":"Insulation types","kind":"fact","front":"What is the difference between organic and inorganic insulation? Give one example of each.","back":"Organic: hydrocarbon polymers expanded into a high-void structure, e.g. thermocol (expanded polystyrene) and polyurethane foam. Inorganic: siliceous, aluminous or calcium material in fibrous, granular or powder form, e.g. mineral wool and calcium silicate.","explain":"The split is by base material. The chapter uses expanded polystyrene mainly for cold insulation of piping and cold stores, while calcium silicate suits high service temperatures.","flash":false,"source":"BEE Book 2 Ch 05 p174","order":2256},
{"id":"p2-b05-006","paper":2,"topic":"Insulation types","kind":"fact","front":"Why is calcium silicate chosen for industrial process piping?","back":"It gives high service temperature and high compressive strength, and is used over about 40 °C to 950 °C.","explain":"Process piping needs both heat resistance and strength under load, and calcium silicate offers both over a wide temperature range.","flash":false,"source":"BEE Book 2 Ch 05 p174","order":2257},
{"id":"p2-b05-007","paper":2,"topic":"Thermal conductivity","kind":"fact","front":"Define thermal conductivity and give its unit.","back":"The heat loss per unit area, per unit insulation thickness, per unit temperature difference. Unit: W/m·°C.","explain":"A lower conductivity means a better insulator, so for a given thickness the lowest-conductivity material is preferred.","flash":true,"source":"BEE Book 2 Ch 05 p175","order":2258},
{"id":"p2-b05-008","paper":2,"topic":"Thermal conductivity","kind":"fact","front":"Does the thermal conductivity of insulation rise or fall with temperature, and at what temperature is it quoted?","back":"It rises with temperature, so it is quoted at the mean temperature of the insulation (the mean of the hot and cold face temperatures).","explain":"A common trap is using the hot-face or ambient temperature for k. The book's worked example uses the mean of the hot and cold face temperatures.","flash":false,"source":"BEE Book 2 Ch 05 p175","order":2259},
{"id":"p2-b05-009","paper":2,"topic":"Heat loss calculation","kind":"fact","front":"Write the basic heat-loss equation for a surface and define Ts and Ta.","back":"H = h × A × (Ts − Ta) watts. Ts is the desired or actual insulation surface temperature (°C), Ta the average ambient temperature (°C), h the heat transfer coefficient (W/m²·K) and A the surface area (m²).","explain":"The surface temperature Ts is the design target. In the trial method, the surface temperature is adjusted until the insulation thickness is close to a standard size.","flash":false,"source":"BEE Book 2 Ch 05 p175","order":2260},
{"id":"p2-b05-010","paper":2,"topic":"Economic thickness","kind":"fact","front":"Why is there an economic limit to how much insulation is worth fitting?","back":"Insulation follows the law of decreasing returns: each extra thickness saves less heat, so beyond a point the extra cost is not recovered through small heat savings.","explain":"Insulation is a capital expense, so the key analysis is cost against heat saved. The thickness at which total cost is lowest is the economic thickness.","flash":false,"source":"BEE Book 2 Ch 05 p177","order":2261},
{"id":"p2-b05-011","paper":2,"topic":"Economic thickness","kind":"fact","front":"Name any five factors needed to determine economic insulation thickness.","back":"Any five of: cost of fuel; annual hours of operation; heat content (GCV) of fuel; boiler efficiency; operating surface temperature; pipe diameter or surface thickness; estimated cost of insulation; average ambient still-air temperature.","explain":"Each factor changes either the annual cost of the heat lost or the cost of the insulation. Fuel cost and heat content together set the value of the heat lost.","flash":false,"source":"BEE Book 2 Ch 05 p177","order":2262},
{"id":"p2-b05-012","paper":2,"topic":"Economic thickness","kind":"fact","front":"On the economic thickness curve, what happens to total cost as insulation thickness increases?","back":"It falls at first, reaches a minimum at the economic thickness, then rises. The curve is the fuel cost of heat loss combined with the depreciation cost of the insulation.","explain":"Beyond the economic thickness, the extra insulation costs more than the fuel it saves.","flash":false,"source":"BEE Book 2 Ch 05 p177","order":2263},
{"id":"p2-b05-013","paper":2,"topic":"Economic thickness","kind":"fact","front":"Over how many years does the BEE procedure take the NPV of future energy costs for insulation?","back":"Typically 5 years, the assumed insulation life. The book's example uses a 15% discount factor.","explain":"Future fuel losses are discounted to present value, so a saving in year five is worth less than one in year one. The total cost used to pick thickness includes both the NPV of losses and the insulation cost.","flash":true,"source":"BEE Book 2 Ch 05 p178","order":2264},
{"id":"p2-b05-014","paper":2,"topic":"Economic thickness","kind":"fact","front":"What is the final step in the economic thickness procedure?","back":"Choose the insulation thickness with the lowest total cost, i.e. the NPV of energy losses plus the material and labour cost of the insulation.","explain":"The procedure tests standard thicknesses (1, 2 or 3 inch in the book's example), computes both cost components for each, and compares the totals.","flash":false,"source":"BEE Book 2 Ch 05 p178","order":2265},
{"id":"p2-b05-015","paper":2,"topic":"Heat loss calculation","kind":"fact","front":"Up to what surface temperature is the BEE simplified heat-loss formula valid, and what does it leave out?","back":"Up to 200 °C surface temperature. It ignores wind velocity and the conductivity of the insulating material.","explain":"The formula is S = [10 + (Ts − Ta)/20] × (Ts − Ta) kcal/h·m². For higher surfaces, the book points to charts and references instead.","flash":false,"source":"BEE Book 2 Ch 05 p180","order":2266},
{"id":"p2-b05-016","paper":2,"topic":"Heat loss calculation","kind":"fact","front":"How is annual heat loss turned into money using the simplified method?","back":"Equivalent fuel loss (kg/yr) = Hs × yearly operating hours ÷ (GCV × boiler efficiency); annual monetary loss = fuel loss × fuel cost per kg.","explain":"Hs is the total heat loss per hour (S × A) in kcal/h. Boiler efficiency is entered as a fraction in the calculation, so 80% becomes 0.8.","flash":false,"source":"BEE Book 2 Ch 05 p180","order":2267},
{"id":"p2-b05-017","paper":2,"topic":"Cold insulation","kind":"fact","front":"When is cold insulation needed?","back":"Where the operating temperature is below ambient, to protect against heat gain, condensation or freezing.","explain":"Condensation forms when moist air touches a surface below its dew point. Heat gained by uninsulated chilled-water lines also lowers the efficiency of the cooling system.","flash":false,"source":"BEE Book 2 Ch 05 p181","order":2268},
{"id":"p2-b05-018","paper":2,"topic":"Cold insulation","kind":"fact","front":"In cold insulation, what is the main economic concern, unlike hot insulation?","back":"Heat gain into the refrigerated space, which raises the refrigeration load (TR) and energy consumption.","explain":"The cost of that heat gain is compared with the cost of extra cold insulation thickness, to optimise total energy and cost in the refrigeration system.","flash":false,"source":"BEE Book 2 Ch 05 p182","order":2269},
{"id":"p2-b05-019","paper":2,"topic":"Refractory basics","kind":"fact","front":"What is a refractory?","back":"A material that can withstand the action of abrasive or corrosive solids, liquids or gases at high temperatures. Examples: fireclay, alumina, magnesite, chrome magnesite, dolomite.","explain":"Refractories are used in metal extraction, cement, glassmaking and ceramic processes, where the high-temperature process is also corrosive or abrasive.","flash":false,"source":"BEE Book 2 Ch 05 p182","order":2270},
{"id":"p2-b05-020","paper":2,"topic":"Refractory properties","kind":"fact","front":"Why does the pyrometric cone equivalent (PCE) not fully predict refractory performance in service?","back":"PCE shows only the softening temperature from the cone test. Under load a refractory can deform at a much lower temperature, and a reducing atmosphere can change PCE drastically.","explain":"That is why the refractoriness-under-load (RUL) test is also used: it gives the temperature at which bricks collapse under a similar load in service.","flash":true,"source":"BEE Book 2 Ch 05 p183","order":2271},
{"id":"p2-b05-021","paper":2,"topic":"Refractory properties","kind":"fact","front":"Should a recuperator or regenerator refractory have high or low thermal conductivity, and why?","back":"High, because heat must pass through the brickwork. For conserving heat elsewhere in a furnace, low conductivity is preferred.","explain":"The same property can help or hurt depending on the job. Insulation for heat conservation needs low conductivity, while heat transfer through brickwork needs high conductivity.","flash":false,"source":"BEE Book 2 Ch 05 p183","order":2272},
{"id":"p2-b05-022","paper":2,"topic":"Refractory properties","kind":"fact","front":"What happens to the hot-face temperature when back-up insulation is added behind a refractory?","back":"It conserves heat but increases the hot-face temperature, so the refractory must withstand more and its quality demand goes up.","explain":"Back-up insulation cuts the heat lost through the wall, but the hotter inner face puts more stress on the refractory.","flash":false,"source":"BEE Book 2 Ch 05 p183","order":2273},
{"id":"p2-b05-023","paper":2,"topic":"Refractory properties","kind":"fact","front":"Why are lightweight, low-conductivity refractories preferred in batch-type furnaces?","back":"Their low heat capacity minimises the heat stored in the structure during intermittent heating and cooling cycles.","explain":"In a batch furnace, heat stored in the lining is largely lost in each idle period, so a lighter lining wastes less. These refractories suit moderately low temperature heat-treatment furnaces.","flash":false,"source":"BEE Book 2 Ch 05 p184","order":2274},
{"id":"p2-b05-024","paper":2,"topic":"Refractory classification","kind":"fact","front":"How are refractories classified by chemical composition?","back":"Acid (silica, semisilica, aluminosilicate), basic (magnesite, chrome-magnesite, dolomite), neutral (chrome, pure alumina) and special (carbon, silicon carbide, zirconia).","explain":"Acid refractories combine with bases, basic ones resist bases, and neutral ones react with neither acids nor bases.","flash":false,"source":"BEE Book 2 Ch 05 p184","order":2275},
{"id":"p2-b05-025","paper":2,"topic":"Refractory types","kind":"fact","front":"What defines a high-alumina refractory, and what does refractoriness do as alumina rises?","back":"An alumino-silicate material with more than 45% alumina (range 45 to 100%). Refractoriness increases with the alumina percentage.","explain":"High-alumina refractories are used in blast furnace hearths and shafts, ceramic and cement kilns, glass tanks and melting crucibles.","flash":false,"source":"BEE Book 2 Ch 05 p186","order":2276},
{"id":"p2-b05-026","paper":2,"topic":"Refractory types","kind":"fact","front":"What is silica brick, and how does it behave under high load?","back":"Silica (Dinas) brick contains at least 93% SiO₂. It does not begin to soften under high load until its fusion point is approached.","explain":"Alumino-silicate refractories begin to creep at temperatures well below their fusion points. Silica brick is used in glass-making and steel furnaces.","flash":false,"source":"BEE Book 2 Ch 05 p186","order":2277},
{"id":"p2-b05-027","paper":2,"topic":"Refractory types","kind":"fact","front":"What is the minimum MgO content of a magnesite refractory, and what is its chemical nature?","back":"At least 85% MgO. It is chemically basic, made from naturally occurring magnesite (MgCO₃), and has very high slag resistance, particularly to lime and iron-rich slags.","explain":"Good quality magnesite usually has a CaO-SiO₂ ratio below 2 and a minimum ferrite concentration.","flash":false,"source":"BEE Book 2 Ch 05 p186","order":2278},
{"id":"p2-b05-028","paper":2,"topic":"Refractory types","kind":"fact","front":"Why is zirconia used as a high-temperature refractory and in glass furnaces?","back":"It keeps very high strength up to about 1500 °C, its thermal conductivity is lower than most refractories, and it is not easily wetted by molten glass. It must be stabilised (e.g. with calcium, magnesium or cerium oxide) before use.","explain":"Zirconia is polymorphic, so its properties depend on the degree and quantity of stabilisation as well as the raw material quality.","flash":false,"source":"BEE Book 2 Ch 05 p187","order":2279},
{"id":"p2-b05-029","paper":2,"topic":"Insulating materials","kind":"fact","front":"Name the five groups of insulating refractory materials.","back":"Insulating bricks; insulating castables; ceramic fibre; calcium silicate; ceramic coating.","explain":"Insulating refractories cut wall losses by placing a low-conductivity layer between the hot furnace interior and the outer surface, so the outer surface runs cooler.","flash":false,"source":"BEE Book 2 Ch 05 p188","order":2280},
{"id":"p2-b05-030","paper":2,"topic":"Insulating materials","kind":"fact","front":"Where does the low thermal conductivity of insulating refractories come from?","back":"From their pores: the minute air-filled pores themselves have very low conductivity. Their heat capacity depends on bulk density and specific heat.","explain":"The choice of insulating material depends on both its resistance to heat conduction and the temperature it can withstand before its properties degrade.","flash":true,"source":"BEE Book 2 Ch 05 p188","order":2281},
{"id":"p2-b05-031","paper":2,"topic":"Ceramic fibre","kind":"fact","front":"How is ceramic fibre made?","back":"Alumina and silica are melted at about 1800 to 2000 °C, and the stream is broken by compressed air or the melt is dropped onto a spinning disc to form bulk fibre.","explain":"The bulk fibre is then converted into blankets, strips, modules, paper, boards, rope and other forms for insulation.","flash":false,"source":"BEE Book 2 Ch 05 p189","order":2282},
{"id":"p2-b05-032","paper":2,"topic":"Ceramic fibre","kind":"fact","front":"What are the blanket density range and the conductivity of ceramic fibre?","back":"Blanket densities are 64 to 190 kg/m³. A 128 kg/m³ blanket has a conductivity of about 0.1 kcal/m·h·°C at 600 °C.","explain":"The book says this is about 40% better than good insulating brick and 2.5 times better than asbestos product, so thinner linings give the same efficiency.","flash":false,"source":"BEE Book 2 Ch 05 p190","order":2283},
{"id":"p2-b05-033","paper":2,"topic":"Ceramic fibre","kind":"fact","front":"How much heat does a ceramic fibre lining store compared with a conventional lining?","back":"Ceramic fibre: about 2,700 to 4,050 kcal/m² (1,000 to 1,500 Btu/ft²). Conventional lining: about 54,200 to 493,900 kcal/m² (20,000 to 250,000 Btu/ft²).","explain":"Lower heat storage means the furnace can be heated and cooled faster, which suits intermittent operation.","flash":true,"source":"BEE Book 2 Ch 05 p190","order":2284},
{"id":"p2-b05-034","paper":2,"topic":"Ceramic fibre","kind":"fact","front":"How does the weight of ceramic fibre compare with insulating brick, and what structural saving does it allow?","back":"Average density about 96 kg/m³, one tenth the weight of insulating brick and one third that of asbestos or calcium silicate boards. Structural supports for new furnaces can be reduced by about 40%.","explain":"Lighter linings allow shop-fabricated, assembled furnace sections to be shipped to site without damage.","flash":false,"source":"BEE Book 2 Ch 05 p191","order":2285},
{"id":"p2-b05-035","paper":2,"topic":"High emissivity coatings","kind":"fact","front":"What emissivity do high-temperature furnaces typically have, and what can high-emissivity coatings raise it to?","back":"About 0.3 without coating; up to about 0.8 with high-emissivity coatings, which increases radiative heat transfer.","explain":"Emissivity measures a surface's ability to absorb and radiate heat. Coatings raise the emissivity of the surface, which conductivity-based changes cannot easily do.","flash":true,"source":"BEE Book 2 Ch 05 p192","order":2286},
{"id":"p2-b05-036","paper":2,"topic":"Refractory selection","kind":"fact","front":"List the main factors to consider when selecting a refractory.","back":"Area of application; working temperature; abrasion and impact; structural load; stress from temperature gradients and fluctuations; chemical compatibility with the furnace environment; heat transfer and fuel conservation; cost.","explain":"Temperature is by no means the only criterion. The gaseous atmosphere, the presence of slags and the type of metal charge also determine the choice.","flash":false,"source":"BEE Book 2 Ch 05 p192","order":2287},
{"id":"p2-b05-037","paper":2,"topic":"Furnace wall losses","kind":"fact","front":"Name four factors on which heat losses through furnace walls depend.","back":"Emissivity of the walls; conductivity of the refractories; wall thickness; and whether the furnace runs continuously or intermittently.","explain":"Wall losses can be reduced by a thicker wall or by insulating bricks, which conduct less heat than refractory brick.","flash":false,"source":"BEE Book 2 Ch 05 p193","order":2288},
{"id":"p2-b05-038","paper":2,"topic":"Furnace wall losses","kind":"fact","front":"In a batch furnace, why is heat stored in the refractories a loss?","back":"During the off period the stored heat is dissipated from the cold face by radiation and convection, and some is carried away by air flowing through the furnace. It must be supplied again in the next on period, so fuel is spent regenerating it.","explain":"If a furnace runs 24 hours every third day, practically all the heat stored in the refractories is lost.","flash":false,"source":"BEE Book 2 Ch 05 p193","order":2289},
{"id":"p2-b05-039","paper":2,"topic":"Economic thickness","kind":"problem","front":"An 8 bar steam pipeline, 168 mm (6 in) outer diameter and 50 m long, with ambient 30 °C, is to be insulated with mineral wool. Comparing 1 in, 2 in and 3 in insulation, which thickness is economic, and what are the total costs?","back":"2 inch (about 50 mm). Total cost (insulation plus NPV of 5-year heat loss): 1 inch Rs 176,698; 2 inch Rs 126,832; 3 inch Rs 129,112.","explain":"The lowest total is the economic thickness. 1 inch saves less heat, while 3 inch costs more to fit than its extra saving over the NPV period.","flash":false,"source":"BEE Book 2 Ch 05 p179","steps":[{"prompt":"Find the heat loss from the bare pipe (h = 15 W/m²·K, A = 26.38 m², Th = 160 °C, Ta = 30 °C).","answer":"Q = h × A × (Th − Ta) = 15 × 26.38 × 130 ≈ 51.4 kW.","explain":"The bare-pipe loss is the reference; each insulated case is compared against it."},{"prompt":"Compute the power saved for each thickness, P = Q − Q′.","answer":"Insulated losses Q′ ≈ 5.16, 3.07 and 2.48 kW for 1, 2 and 3 in; power saved ≈ 46.3, 48.4 and 49.0 kW.","explain":"Thicker insulation lowers Q′ further, so the saving grows, but with diminishing returns."},{"prompt":"Find the annual energy saved at 8,000 h/yr.","answer":"E = P × n ≈ 370,203; 386,892 and 391,634 kWh/yr.","explain":"Energy saved is power multiplied by annual operating hours."},{"prompt":"Convert the energy saved into annual money at Rs 1.11/kWh.","answer":"≈ Rs 412,708; 431,313 and 436,599 per year.","explain":"The heat cost of Rs 1.11/kWh comes from steam at Rs 0.70/kg, as in the book's table."},{"prompt":"Compare total cost: NPV of 5-year energy losses plus insulation cost.","answer":"1 in: 154,198 + 22,500 = Rs 176,698; 2 in: 91,832 + 35,000 = Rs 126,832; 3 in: 74,112 + 55,000 = Rs 129,112. Lowest is 2 in.","explain":"The thickness with the lowest combined cost is the economic thickness."}],"order":2290},
{"id":"p2-b05-040","paper":2,"topic":"Heat loss calculation","kind":"problem","front":"A 100 mm steam pipeline, 100 m long, carries steam at 10 kg/cm² and is uninsulated with a 170 °C surface. With 65 mm insulation the surface falls to 65 °C. Ambient is 25 °C, boiler efficiency 80%, fuel oil GCV 10,300 kcal/kg, and the plant runs 8,400 h/yr. Find the annual fuel oil saving in kg.","back":"About 44,695 kg of fuel oil per year. Heat loss falls from about 78,500 to 34,656 kcal/h.","explain":"The simplified formula gives loss per m² of surface; multiplying by area and hours gives heat, and dividing by GCV × boiler efficiency gives fuel.","flash":false,"source":"BEE Book 2 Ch 05 p181","steps":[{"prompt":"Find the existing surface heat loss S1 at 170 °C with ambient 25 °C.","answer":"S1 = [10 + (170 − 25)/20] × (170 − 25) = 17.25 × 145 ≈ 2,500 kcal/h·m².","explain":"170 °C is within the formula's 200 °C validity limit."},{"prompt":"Find the insulated surface heat loss S2 at 65 °C.","answer":"S2 = [10 + (65 − 25)/20] × (65 − 25) = 12 × 40 = 480 kcal/h·m².","explain":"A cooler surface loses much less heat per m²."},{"prompt":"Find the surface areas before and after insulation.","answer":"A1 = 3.14 × 0.1 × 100 = 31.4 m²; A2 = 3.14 × 0.23 × 100 = 72.2 m².","explain":"Insulated outer diameter is 100 + 2 × 65 = 230 mm."},{"prompt":"Find total heat loss before and after, and the reduction.","answer":"Before: 2,500 × 31.4 = 78,500 kcal/h; after: 480 × 72.2 = 34,656 kcal/h; reduction = 43,844 kcal/h.","explain":"The reduction in kcal/h is the basis for the annual figure."},{"prompt":"Convert the reduction into an annual fuel oil saving.","answer":"Annual heat = 43,844 × 8,400 = 368,289,600 kcal/yr; fuel = 368,289,600 ÷ (10,300 × 0.8) ≈ 44,695 kg/yr.","explain":"Dividing by GCV × boiler efficiency gives the fuel that must be burnt to supply that heat."}],"order":2291}
]$cards$::jsonb);
